const LEVELS = ["low", "medium", "high"] as const;
type Level = (typeof LEVELS)[number];
//   ^? type Level = "high" | "low" | "medium"

type Task = { title: string; priority: Level };

const tasks: Task[] = [
  { title: "Update docs", priority: "low" },
  { title: "Fix login bug", priority: "high" },
  { title: "Review PR", priority: "medium" },
];

const byPriority = tasks.toSorted((a, b) => LEVELS.indexOf(b.priority) - LEVELS.indexOf(a.priority));

for (const task of byPriority) {
  console.log(`${task.priority}: ${task.title}`);
}

const Color = { Red: "red", Green: "green", Blue: "blue" } as const;
type Color = (typeof Color)[keyof typeof Color];

function hex(color: Color): string {
  switch (color) {
    case Color.Red:
      return "#ff0000";
    case Color.Green:
      return "#00ff00";
    case Color.Blue:
      return "#0000ff";
  }
}

console.log(Color.Green);
console.log(hex(Color.Red));
console.log(hex("blue"));

const Priority = { Low: "low", Medium: "medium", High: "high" } as const;
type Priority = (typeof Priority)[keyof typeof Priority];

type Ticket = { id: number; priority: Priority };

function responseHours(priority: Priority): number {
  switch (priority) {
    case Priority.Low:
      return 72;
    case Priority.Medium:
      return 24;
    case Priority.High:
      return 4;
    default: {
      const unreachable: never = priority;
      throw new Error(`Unknown priority: ${unreachable}`);
    }
  }
}

const ticket: Ticket = { id: 7, priority: Priority.High };
console.log(JSON.stringify(ticket));
console.log(`Respond within ${responseHours(ticket.priority)} hours`);
console.log(Object.values(Priority).join(", "));

