practice.solution:
export const LogLevel = {
  Debug: "debug",
  Info: "info",
  Warn: "warn",
  Error: "error",
} as const;

export type LogLevel = (typeof LogLevel)[keyof typeof LogLevel];

const ORDER: readonly LogLevel[] = [LogLevel.Debug, LogLevel.Info, LogLevel.Warn, LogLevel.Error];

export function shouldLog(level: LogLevel, min: LogLevel): boolean {
  return ORDER.indexOf(level) >= ORDER.indexOf(min);
}

const checks: [LogLevel, LogLevel][] = [
  [LogLevel.Debug, LogLevel.Info],
  [LogLevel.Info, LogLevel.Info],
  [LogLevel.Error, LogLevel.Warn],
  [LogLevel.Warn, LogLevel.Error],
];

for (const [level, min] of checks) {
  console.log(`${level} at min ${min}: ${shouldLog(level, min)}`);
}

