const Permission = { Read: 1, Write: 2, Delete: 4 } as const;
type PermissionValue = (typeof Permission)[keyof typeof Permission];
//   ^? type PermissionValue = 1 | 2 | 4

function can(perms: number, p: PermissionValue): boolean {
  return (perms & p) !== 0;
}

const viewer = Permission.Read;
const editor = Permission.Read | Permission.Write;
const admin = editor | Permission.Delete;

console.log(`editor mask: ${editor}`);
console.log(`editor can write: ${can(editor, Permission.Write)}`);
console.log(`viewer can delete: ${can(viewer, Permission.Delete)}`);
console.log(`admin can delete: ${can(admin, Permission.Delete)}`);

import { readFileSync } from "node:fs";

const LEVELS = ["low", "medium", "high"] as const;
type Level = (typeof LEVELS)[number];

function isLevel(x: string): x is Level {
  return LEVELS.some((level) => level === x);
}

const lines = readFileSync(0, "utf8").trim().split("\n");

for (const line of lines) {
  const text = line.trim().toLowerCase();
  if (isLevel(text)) {
    console.log(`ok: ${text}`);
    //                 ^? const text: "high" | "low" | "medium"
  } else {
    console.log(`not a level: ${line}`);
  }
}

examples.explanation:
Everything read from input is a `string`, and a `string` isn't a `Level` until you check it. `isLevel` compares `x` with each allowed value, and its return type `x is Level` makes it a type guard, so inside the `if` the checker treats `text` as a `Level`, as the bubble shows. `LEVELS.includes(x)` looks like the obvious check, but `includes` on this array only takes a `Level`, so it rejects a plain `string`:

```typescript error
const LEVELS = ["low", "medium", "high"] as const;

function isLevel(x: string): boolean {
  return LEVELS.includes(x);
}

console.log(isLevel("low"));
```

`some` with `===` compares the string with each level, which the checker allows.

