export const Permission = { Read: 1, Write: 2, Delete: 4 } as const;

export type PermissionValue = (typeof Permission)[keyof typeof Permission];

export function grant(perms: number, p: PermissionValue): number {
  return perms | p;
}

export function has(perms: number, p: PermissionValue): boolean {
  return (perms & p) !== 0;
}

let perms = 0;
perms = grant(perms, Permission.Read);
perms = grant(perms, Permission.Delete);

console.log(`read: ${has(perms, Permission.Read)}`);
console.log(`write: ${has(perms, Permission.Write)}`);
console.log(`delete: ${has(perms, Permission.Delete)}`);
console.log(`mask: ${perms}`);

